// Deterministic escalation rule engine.
// Reads fields from top-level (agent tool call) OR nested consolidated_event (wf05 gate call).
// consolidated_event may arrive as a STRING (stringifi ed JSON) - parse it if so.
const out = [];
for (const item of $input.all()) {
const j = item.json;
let ce = j.consolidated_event;
if (typeof ce === 'string') {
try { ce = JSON.parse(ce); } catch (e) { ce = {}; }
}
ce = ce || {};
const d = {
status_description: j.status_description ?? ce.status_description ?? '',
attempt_number: j.attempt_number ?? ce.attempt_number,
package_type: j.package_type ?? ce.package_type,
status_code: j.status_code ?? ce.status_code,
customer_tier: j.customer_tier ?? ce.customer_tier ?? 'STANDARD',
exceptions_last_90d:j.exceptions_last_90d ?? ce.exceptions_last_90d ?? 0,
};
const desc = String(d.status_description || '').toLowerCase();
const triggers = [];
// --- AUTOMATIC (mandatory) escalations ---
if (Number(d.attempt_number) >= 3) {
triggers.push('AUTOMATIC: 3rd failed delivery attempt');
}
if (d.customer_tier === 'VIP' && Number(d.exceptions_last_90d) >= 3) {
triggers.push(`AUTOMATIC: VIP customer with ${d.exceptions_last_90d} exceptions in 90d (>=3)`);
}
if (d.status_code === 'DAMAGED' && d.package_type === 'PERISHABLE') {
  triggers.push('AUTOMATIC: Damaged perishable package');
}
if (d.status_code === 'WEATHER_DELAY' && d.package_type === 'PERISHABLE') {
const m = desc.match(/(\d+(?:\.\d+)?)\s*(?:hr|hour|hours)/);
if (m && parseFloat(m[1]) > 4) {
triggers.push(`AUTOMATIC: Perishable with ${parseFloat(m[1])}hr delay (>4hr threshold)`);
}
}
if (d.status_code === 'ADDRESS_ISSUE' &&
['vacant','demolished','construction site','empty lot'].some(k => desc.includes(k))) {
triggers.push('AUTOMATIC: Potential fraud - address is vacant/demolished');
}
// --- DISCRETIONARY (supervisor judgement) escalations ---
if (d.customer_tier === 'STANDARD' && Number(d.exceptions_last_90d) > 5) {
triggers.push(`DISCRETIONARY: Standard customer with ${d.exceptions_last_90d} exceptions in 90d (>5)`);
}
if (d.customer_tier === 'PREMIUM' && d.package_type === 'PERISHABLE' && d.status_code === 'WEATHER_DELAY') {
triggers.push('DISCRETIONARY: Premium customer with perishable in weather delay');
}
out.push({ json: {
triggers,
has_triggers: triggers.length > 0,
trigger_count: triggers.length,
has_automatic: triggers.some(x => x.startsWith('AUTOMATIC')),
}});
}
return out;

