  // 1. Grab the target shipment identifier from the active item

  const currentTargetId = $('Aggregate all the outputs for that shipment ID - aggregage node').item.json.target_shipment_identifier;
  if (!currentTargetId) return { error: "No target_shipment_identifier found in input" };

 // 2. Filter the raw rows down to only match this specific identifier
const rows = $('Select shipment ID to process - edit node')
  .all()
  .map(item => item.json)
  .filter(r => Array.isArray(currentTargetId) ? currentTargetId.includes(r.shipment_id) : r.shipment_id === currentTargetId);

  // 3. Run the processing rules on just those filtered rows
  const uniq = rows.filter(r => String(r.is_duplicate_scan) !== 'True'); 
  const primary = uniq.reduce((a, b) => (Number(b.attempt_number) > Number(a.attempt_number) ? b : a), uniq[0] || rows[0] || {}); 
  const notes = uniq.filter(r => r !== primary).map(r => 'Attempt ' + r.attempt_number + ': ' + r.status_description); 

  return { 
    shipment_id: primary.shipment_id, 
    timestamp: primary.timestamp, 
    status_code: primary.status_code, 
    status_description: primary.status_description, 
    customer_id: primary.customer_id, 
    delivery_address: primary.delivery_address, 
    package_type: primary.package_type, 
    package_size: primary.package_size, 
    attempt_number: Number(primary.attempt_number) || null, 
    prior_attempt_notes: notes, 
    total_rows: rows.length, 
    duplicates_removed: rows.length - uniq.length 
  }; 
})() }}

={{ (() => {
  const currentTargetId = $json.target_shipment_identifier;
  if (!currentTargetId) return "";

  const rows = $('Select shipment ID to process - edit node')
    .all()
    .map(item => item.json)
    .filter(r => Array.isArray(currentTargetId) ? currentTargetId.includes(r.shipment_id) : r.shipment_id === currentTargetId);

  if (!rows.length) return "";

  const primary = rows.reduce((a, b) => (Number(b.attempt_number) > Number(a.attempt_number) ? b : a), rows[0] || {});
  const address = primary.delivery_address || "";

  return address.includes(',') ? address.split(',').pop().trim() : address.trim();
})() }}

